<?php
/** Staff overview retains simple native links and the existing card system. */
$r=$this->getObject('webinarrenderer','webinar');$e=['webinarrenderer','escape'];$kind=$this->getVar('webinarEditKind');
echo '<section class="chisimba-form-card chisimba-form-card--wide"><header class="chisimba-form-actions"><h1>'.$e($r->text($kind==='speaker'?'manage_speakers':'manage')).'</h1>'.$this->getObject('contextualhelp','help')->show('webinar','editing',true).'</header><nav class="chisimba-form-actions">'.$r->button($kind==='speaker'?'add_speaker':'add','plus',['action'=>'edit','kind'=>$kind]).$r->button($kind==='speaker'?'manage':'manage_speakers','list',['action'=>'manage','kind'=>$kind==='speaker'?'webinar':'speaker']).$r->button('title','calendar',['action'=>'upcoming']).'</nav>';
$rows=$this->getObject('webinareditstore','webinar')->listing($kind);$pages=max(1,(int)ceil(count($rows)/12));$page=max(1,min($pages,(int)$this->getParam('page',1)));
echo '<div class="chisimba-publication-card-grid">';foreach(array_slice($rows,($page-1)*12,12) as $row)echo '<article class="chisimba-publication-card"><div class="chisimba-publication-card__body"><h2>'.$e(html_entity_decode($row['title'],ENT_QUOTES|ENT_HTML5,'UTF-8')).'</h2><p>'.$e($r->text($row['status']==='published'?'editor_published':'editor_draft')).'</p>'.$r->date($row).'<div class="chisimba-form-actions">'.$r->button('edit','pencil',['action'=>'edit','id'=>$row['id']]).$r->button('preview','eye',['action'=>'preview','id'=>$row['id']]).'</div></div></article>';echo '</div><nav class="chisimba-form-actions">';if($page>1)echo $r->button('previous','chevron-left',['action'=>'manage','kind'=>$kind,'page'=>$page-1]);if($page<$pages)echo $r->button('next','chevron-right',['action'=>'manage','kind'=>$kind,'page'=>$page+1]);echo '</nav></section>';
